// Generated by `cargo xtask add-card`.
// Round-trip regression test for the generated test suite.
//
// Card           : Pestilence
// Set            : lea
// Collector #    : 120

#[test]
fn round_trip() {
    let text = "At the beginning of the end step, if no creatures are on the battlefield, sacrifice this enchantment.\n{B}: This enchantment deals 1 damage to each creature and each player.";
    let ast = mtg_grammar::parse(text).expect("parse");
    let reprinted = mtg_grammar::unparse(&ast);
    assert_eq!(
        reprinted, text,
        "unparse must preserve the normalized oracle text"
    );
    let ast2 = mtg_grammar::parse(&reprinted).expect("reparse");
    assert_eq!(ast, ast2);
}
